import com.comsol.model.*;import com.comsol.model.util.*;import java.util.*;
/** Native Plasma finite-volume collision operator. Transport is intentionally
 * zero during this split substep; material/chemical advection belongs to FV.
 * This first fixture is a closed uniform box, not a plume image prediction. */
public class BuildReactionOperator{
 static Model m;static void v(String n,String e){m.component("c").variable("gasv").set(n,e);}static void ov(String f,String n,String e){m.component("c").physics("plas").feature(f).featureInfo("info").set(n,new String[]{e});}
 public static void main(String[] a){try{
 ModelUtil.initStandalone(false);m=ModelUtil.create("reactionOperator");String root=a[0],name=a[1];
 for(String[] p:new String[][]{{"Tamb","293.15[K]"},{"pAmb","101325[Pa]"},{"rhoCuCell","1[kg/m^3]"},{"rhoAirCell","0.1[kg/m^3]"},{"Tcell","8000[K]"},{"seedNe","1e9[1/m^3]"},{"Mcu","0.063546[kg/mol]"},{"Mair","0.79*0.0280134[kg/mol]+0.21*0.0319988[kg/mol]"},{"Bcu","5815069.632191036[J/kg]"},{"w0","11[um]"},{"lambdaL","1064[nm]"},{"Acu","0.1"},{"Lv","5069000[J/kg]"},{"Tv","2836[K]"},{"workCu","4.65[V]"},{"rhoCu","8960[kg/m^3]"},{"accom","1"},{"meltOn","0"},{"eScale","1e6[J/m^3]"},{"tEnd","100[ns]"}})m.param().set(p[0],p[1]);
 m.component().create("c",true);m.component("c").geom().create("g",2);m.component("c").geom("g").axisymmetric(true);m.component("c").geom("g").create("gas","Rectangle");m.component("c").geom("g").feature("gas").set("size",new String[]{"20[um]","20[um]"});m.component("c").geom("g").feature("gas").set("selresult",true);m.component("c").geom("g").run();
 for(String tag:new String[]{"gasv","boundv"})m.component("c").variable().create(tag);
 m.component("c").physics().create("plas","ColdPlasma","g");m.component("c").physics("plas").selection().all();m.component("c").physics("plas").prop("ShapeProperty").set("Formulation","FVMConst");
 Chemistry.apply(m,root+"/data");GasFields.apply(m,false);RecombinationEnergy.apply(m);ThermalBalance.apply(m);NeutralCollisionCount.apply(m);
 v("rhoP","rhoCuCell+rhoAirCell");v("Tg","1[K]*exp(logTg)");v("urP","0[m/s]");v("uzP","0[m/s]");v("divU","0[1/s]");v("Dgas","0[m^2/s]");v("Qlaser","0[W/m^3]");
 v("nMol0","rhoCuCell/Mcu+rhoAirCell/Mair");v("Cv0","R_const*(1.5*rhoCuCell/Mcu+2.5*rhoAirCell/Mair)");v("initialEnergy","Cv0*Tcell+Bcu*rhoCuCell+15.58[V]*e_const*seedNe+1.5*seedNe*k_B_const*Tamb");
 m.component("c").physics("plas").prop("DiffusionModel").set("DiffusionModel","FicksLaw");m.component("c").physics("plas").prop("TransportSettings").set("Convection",false);m.component("c").physics("plas").prop("ElectronProperties").set("MeanElectronEnergyModel","LocalEnergyApproximationE");
 for(String k:new String[]{"SourceStabilization","ReactionSourceStabilization"})m.component("c").physics("plas").prop("Stabilization").set(k,false);
 m.component("c").physics("plas").feature("pes1").set("DensityType","DensityType");m.component("c").physics("plas").feature("pes1").set("rho","rhoP");m.component("c").physics("plas").feature("pes1").set("T","Tg");m.component("c").physics("plas").feature("pes1").set("pA","pHeavy");m.component("c").physics("plas").feature("pes1").set("u",new String[]{"0","0","0"});m.component("c").physics("plas").feature("pes1").set("SpecifyElectronDensityAndEnergy","SpecifyMueOnly");m.component("c").physics("plas").feature("pes1").set("mue","e_const/(me_const*nuCollision)");
 ov("pes1","plas.sg_flux_ne","0[1/(m^2*s)]");ov("pes1","plas.sg_flux_en","0[V/(m^2*s)]");ov("pes1","plas.Pcap","0[W/m^3]");ov("pes1","plas.Nn0","nMol0*N_A_const");
 for(String n:Chemistry.NAMES){
  if(!n.equals("N2"))ov(n,"plas.sg_flux_w"+n,"0[kg/(m^2*s)]");
  m.component("c").physics("plas").feature(n).set("x0",n.equals("Cu")?"rhoCuCell/Mcu/nMol0":n.equals("O2")?"0.21*rhoAirCell/Mair/nMol0":"1e-24");
  if(n.endsWith("_1p")||n.endsWith("_1m"))m.component("c").physics("plas").feature(n).set("n0",n.equals("N2_1p")?"seedNe":"1e-12[1/m^3]");
 }
 m.component("c").physics("plas").feature("N2_1p").set("InitIon",false);
 m.component("c").physics("plas").feature("init1").set("neinit","seedNe");m.component("c").physics("plas").feature("init1").set("ebarinit","1.5*k_B_const*Tamb/e_const");
 for(String n:Chemistry.NAMES)if(n.equals("N")||n.equals("O")||(n.startsWith("Cu")&&!n.equals("Cu_1p"))){String tag="elasticAtom"+n;m.component("c").physics("plas").create(tag,"ElectronImpactReaction",2);m.component("c").physics("plas").feature(tag).set("formula","e+"+n+"=>e+"+n);m.component("c").physics("plas").feature(tag).set("type","Elastic");m.component("c").physics("plas").feature(tag).set("kf","kmCu*N_A_const");m.component("c").physics("plas").feature(tag).set("mratio","me_const*N_A_const/plas.M_w"+n);}
 m.component("c").physics("plas").create("power","GeneralPowerDeposition",2);m.component("c").physics("plas").feature("power").selection().all();m.component("c").physics("plas").feature("power").set("Qgen","Qlaser-QeRR-QeAttach-Qff-Qei");m.component("c").physics("plas").create("ground","Ground",1);m.component("c").physics("plas").feature("ground").selection().all();
 m.component("c").physics().create("reactionEnergy","GeneralFormPDE","g",new String[]{"qrE","logTg"});m.component("c").physics("reactionEnergy").feature("gfeq1").set("da",new String[]{"1","0"});m.component("c").physics("reactionEnergy").feature("gfeq1").set("Ga",new String[][]{{"0","0"},{"0","0"}});m.component("c").physics("reactionEnergy").feature("gfeq1").set("f",new String[]{"(Qlaser-Qrad)/eScale","(qrE*eScale-CvVol*Tg-Uchem-Ue)/eScale"});m.component("c").physics("reactionEnergy").feature("init1").set("qrE","initialEnergy/eScale");m.component("c").physics("reactionEnergy").feature("init1").set("logTg","log(Tcell/1[K])");m.component("c").physics("reactionEnergy").prop("ShapeProperty").set("shapeFunctionType","shdisc");m.component("c").physics("reactionEnergy").prop("ShapeProperty").set("order",0);
 m.component("c").mesh().create("mesh");m.component("c").mesh("mesh").create("map","Map");m.component("c").mesh("mesh").feature("map").create("dist","Distribution");m.component("c").mesh("mesh").feature("map").feature("dist").selection().all();m.component("c").mesh("mesh").feature("map").feature("dist").set("numelem",4);m.component("c").mesh("mesh").run();
 m.study().create("std");m.study("std").create("time","Transient");m.study("std").feature("time").set("tlist","range(0,1[ns],tEnd)");m.study("std").feature("time").set("rtol",1e-4);m.study("std").setGenPlots(false);m.study("std").createAutoSequences("sol");
 for(String f:m.sol("sol1").feature("t1").feature().tags())if(Arrays.asList("Segregated","FullyCoupled").contains(m.sol("sol1").feature("t1").feature(f).getType()))m.sol("sol1").feature("t1").feature().remove(f);
 m.sol("sol1").feature("t1").create("direct","Direct");m.sol("sol1").feature("t1").feature("direct").set("linsolver","pardiso");m.sol("sol1").feature("t1").create("all","FullyCoupled");m.sol("sol1").feature("t1").feature("all").set("linsolver","direct");m.sol("sol1").feature("t1").feature("all").set("maxiter",20);m.sol("sol1").feature("t1").set("maxorder",2);m.sol("sol1").feature("t1").set("atolglobal","1e-8");m.sol("sol1").feature("t1").set("maxstepconstraintbdf","const");m.sol("sol1").feature("t1").set("maxstepbdf","0.2[ns]");
 for(String f:m.sol("sol1").feature("v1").feature().tags()){String sc=f.equals("c_Ne")||f.equals("c_En")?"1e12":f.endsWith("_w")?"1e-6":"1";m.sol("sol1").feature("v1").feature(f).set("scalemethod","manual");m.sol("sol1").feature("v1").feature(f).set("scaleval",sc);}
 m.label("Native Plasma collision-only FV operator; closed 16-cell fixture, no plume prediction");m.save(root+"/models/"+name+"_ready.mph");System.out.println("REACTION OPERATOR READY");System.exit(0);
 }catch(Throwable e){e.printStackTrace();System.exit(1);}}}
